INSERT INTO products
  (slug, title, description, category_id, brand, sku, price_pence, stock, image_url, images_json,
   status, featured, source, ebay_item_id, ebay_account, ebay_url, ebay_synced_at)
SELECT i.slug, i.title, i.description, c.id, i.brand, i.sku, i.price_pence, i.stock, i.image_url,
       json_array(i.image_url), 'active', i.featured, 'ebay', i.ebay_item_id, i.ebay_account, i.ebay_url,
       datetime('now')
FROM item i LEFT JOIN categories c ON c.slug = i.cat
WHERE NOT EXISTS (SELECT 1 FROM products p WHERE p.ebay_item_id = i.ebay_item_id);
